import { z } from "zod";
import { AREAS, PRIORITIES, STATUSES } from "./types";

/** Schema of data/seed/activities.v1.json (generated by scripts/import_workbook.py). */
export const fixtureActivitySchema = z.object({
  ID: z.string().regex(/^ACT-\d{2}$/),
  Phase: z.string().regex(/^\d{2} .+/),
  Area: z.enum(AREAS),
  Activity: z.string().min(1),
  Objective: z.string(),
  Tutorial: z.string(),
  Knowledge: z.string(),
  Tool: z.string(),
  Deliverable: z.string(),
  Dependency: z.union([z.literal(""), z.string().regex(/^ACT-\d{2}$/)]),
  Acceptance: z.string().min(1),
  Reference: z.string(),
  Status: z.enum(STATUSES),
  Priority: z.enum(PRIORITIES),
  Owner: z.string(),
  Due: z.union([z.literal(""), z.iso.date()]),
  Evidence: z.string(),
  Notes: z.string(),
});
export type FixtureActivity = z.infer<typeof fixtureActivitySchema>;

export const fixtureSchema = z
  .object({
    version: z.literal(1),
    source: z.object({ file: z.string(), sha256: z.string().length(64), sheet: z.string() }),
    statuses: z.array(z.string()),
    statusDefinitions: z.record(z.string(), z.string()),
    priorities: z.array(z.string()),
    areas: z.array(z.string()),
    phaseArea: z.record(z.string(), z.string()),
    activities: z.array(fixtureActivitySchema).min(1),
  })
  .superRefine((f, ctx) => {
    const ids = f.activities.map((a) => a.ID);
    if (new Set(ids).size !== ids.length) ctx.addIssue({ code: "custom", message: "duplicate activity IDs" });
    for (const a of f.activities) {
      if (a.Dependency && !ids.includes(a.Dependency))
        ctx.addIssue({ code: "custom", message: `${a.ID}: unknown dependency ${a.Dependency}` });
    }
    // Cycle check: follow single-parent dependency chains.
    const dep = new Map(f.activities.map((a) => [a.ID, a.Dependency || null]));
    for (const start of ids) {
      const seen = new Set<string>();
      let cur: string | null = start;
      while (cur) {
        if (seen.has(cur)) {
          ctx.addIssue({ code: "custom", message: `dependency cycle at ${start}` });
          break;
        }
        seen.add(cur);
        cur = dep.get(cur) ?? null;
      }
    }
    if (JSON.stringify(f.statuses) !== JSON.stringify(STATUSES))
      ctx.addIssue({ code: "custom", message: "statuses differ from the 8 workbook statuses" });
  });
export type Fixture = z.infer<typeof fixtureSchema>;
